// ================================================================
// LAYER 3 - NODE 3-1: 데이터 정제/정규화 v2.1
// 입력: 병합된 [0]=Yahoo Finance, [1]=Alpha Vantage
// ================================================================

const items = $input.all();

// 병합 노드에서 오는 데이터: items[0].json 에 두 HTTP 결과가 배열로 있음
// combinationMode: mergeByPosition → input1과 input2가 각각 items[0], items[1]
const yahoo_raw = items[0]?.json || {};
const alpha_raw = items[1]?.json || {};

const fin = yahoo_raw.quoteSummary?.result?.[0];
const fd  = fin?.financialData;
const ks  = fin?.defaultKeyStatistics;
const is_ = fin?.incomeStatementHistory?.incomeStatementHistory?.[0];
const bs  = fin?.balanceSheetHistory?.balanceSheetHistory?.[0];
const cf  = fin?.cashflowStatementHistory?.cashflowStatements?.[0];

const safe = (obj, key, fallback = null) => {
  const val = obj?.[key]?.raw;
  return (val !== undefined && val !== null) ? val : fallback;
};

// 티커: Webhook에서 왔으면 payload, Schedule에서 왔으면 별도 처리
const ticker = alpha_raw.Symbol
  || $('Webhook Trigger').item?.json?.ticker
  || 'UNKNOWN';

return [{
  json: {
    // 메타
    ticker,
    company_name:          alpha_raw.Name,
    sector:                alpha_raw.Sector || null,
    sector_normalized:     (alpha_raw.Sector || '').trim(),
    industry:              alpha_raw.Industry,
    market_cap:            safe(fd, 'marketCap'),
    currency:              fd?.financialCurrency || 'USD',

    // 가격
    current_price:         safe(fd, 'currentPrice'),
    target_price_analyst:  safe(fd, 'targetMeanPrice'),
    // FIX #1: 52주 고/저가 (52WeekChange는 비율이므로 별도 보관)
    fifty_two_week_high:   safe(ks, 'fiftyTwoWeekHigh'),
    fifty_two_week_low:    safe(ks, 'fiftyTwoWeekLow'),
    week_52_change_pct:    safe(ks, '52WeekChange'),
    beta:                  safe(ks, 'beta'),

    // 손익계산서
    revenue:               safe(is_, 'totalRevenue'),
    gross_profit:          safe(is_, 'grossProfit'),
    ebit:                  safe(is_, 'ebit'),
    net_income:            safe(is_, 'netIncome'),
    eps:                   safe(ks, 'trailingEps'),
    eps_forward:           safe(ks, 'forwardEps'),

    // 재무상태표
    total_assets:          safe(bs, 'totalAssets'),
    total_equity:          safe(bs, 'totalStockholderEquity'),
    total_debt:            safe(bs, 'longTermDebt'),
    book_value_per_share:  safe(ks, 'bookValue'),
    shares_outstanding:    safe(ks, 'sharesOutstanding'),

    // 현금흐름
    operating_cash_flow:   safe(cf, 'totalCashFromOperatingActivities'),
    capex:                 safe(cf, 'capitalExpenditures'),
    free_cash_flow:        safe(fd, 'freeCashflow'),

    // 성장률
    revenue_growth:        safe(fd, 'revenueGrowth'),
    earnings_growth:       safe(fd, 'earningsGrowth'),

    // 수익성
    roe:                   safe(fd, 'returnOnEquity'),
    roa:                   safe(fd, 'returnOnAssets'),
    profit_margin:         safe(fd, 'profitMargins'),
    operating_margin:      safe(fd, 'operatingMargins'),

    collected_at:          new Date().toISOString(),
    data_quality_score:    null
  }
}];

// ================================================================
// LAYER 3 - NODE 3-2: PER/PBR/DCF 계산 v2.1
// FIX #2: DCF Phase2 루프 변수 분리 (이중복리 방지)
// FIX #3: 터미널 밸류 오프-바이-원 수정
// FIX #6: 할인율 ≤ 성장률 제로나눗셈 방어
// FIX #7: 음수 EPS PER 역전 방지
// FIX #8: 음수 장부가 PBR 제외
// FIX #9: DCF 루프 음수 FCF 방어
// FIX #10: current_price=0 무한대 방지
// FIX #11: 누락 섹터 6개 추가
// FIX #12: 섹터 이름 대소문자 정규화
// FIX #17: 베타 연동 안전마진 동적 조정
// FIX #18: 가중 데이터 품질 점수
// FIX #19: upside current_price=0 무한대 방지
// ================================================================

const d = $input.first().json;

const pct   = (v) => v != null ? (v * 100).toFixed(2) + '%' : 'N/A';
const ratio = (a, b) => (a != null && b != null && b !== 0) ? (a / b) : null;

// ─── 섹터 벤치마크 (FIX #11: 전 섹터 커버) ────────────────────────
const SECTOR_PER = {
  'Technology':             { fair: 25, overvalued: 35, undervalued: 15 },
  'Information Technology': { fair: 25, overvalued: 35, undervalued: 15 },
  'Finance':                { fair: 12, overvalued: 18, undervalued: 8 },
  'Financial Services':     { fair: 12, overvalued: 18, undervalued: 8 },
  'Healthcare':             { fair: 20, overvalued: 30, undervalued: 12 },
  'Consumer Cyclical':      { fair: 18, overvalued: 28, undervalued: 10 },
  'Consumer Discretionary': { fair: 18, overvalued: 28, undervalued: 10 },
  'Consumer Defensive':     { fair: 16, overvalued: 24, undervalued: 10 },
  'Consumer Staples':       { fair: 16, overvalued: 24, undervalued: 10 },
  'Energy':                 { fair: 10, overvalued: 16, undervalued: 6 },
  'Industrials':            { fair: 16, overvalued: 24, undervalued: 10 },
  'Materials':              { fair: 14, overvalued: 22, undervalued: 8 },
  'Basic Materials':        { fair: 14, overvalued: 22, undervalued: 8 },
  'Real Estate':            { fair: 14, overvalued: 20, undervalued: 8 },
  'Utilities':              { fair: 12, overvalued: 18, undervalued: 8 },
  'Communication Services': { fair: 18, overvalued: 28, undervalued: 10 },
  'default':                { fair: 18, overvalued: 25, undervalued: 10 }
};

const SECTOR_PBR = {
  'Technology':             { fair: 5,   overvalued: 10,  undervalued: 2 },
  'Information Technology': { fair: 5,   overvalued: 10,  undervalued: 2 },
  'Finance':                { fair: 1.2, overvalued: 2,   undervalued: 0.7 },
  'Financial Services':     { fair: 1.2, overvalued: 2,   undervalued: 0.7 },
  'Healthcare':             { fair: 4,   overvalued: 8,   undervalued: 2 },
  'Consumer Cyclical':      { fair: 3,   overvalued: 6,   undervalued: 1 },
  'Consumer Discretionary': { fair: 3,   overvalued: 6,   undervalued: 1 },
  'Consumer Defensive':     { fair: 2.5, overvalued: 5,   undervalued: 1 },
  'Consumer Staples':       { fair: 2.5, overvalued: 5,   undervalued: 1 },
  'Energy':                 { fair: 1.5, overvalued: 3,   undervalued: 0.6 },
  'Industrials':            { fair: 2.5, overvalued: 5,   undervalued: 1 },
  'Materials':              { fair: 2,   overvalued: 4,   undervalued: 0.8 },
  'Basic Materials':        { fair: 2,   overvalued: 4,   undervalued: 0.8 },
  'Real Estate':            { fair: 1,   overvalued: 2,   undervalued: 0.5 },
  'Utilities':              { fair: 1.5, overvalued: 2.5, undervalued: 0.8 },
  'Communication Services': { fair: 3,   overvalued: 6,   undervalued: 1 },
  'default':                { fair: 2,   overvalued: 4,   undervalued: 0.8 }
};

// FIX #12: 대소문자 정규화 후 벤치마크 조회
const findBench = (table, sector) => {
  if (!sector) return table['default'];
  const exact = table[sector.trim()];
  if (exact) return exact;
  const ci = Object.keys(table).find(k => k.toLowerCase() === sector.trim().toLowerCase());
  return ci ? table[ci] : table['default'];
};

const per_bench = findBench(SECTOR_PER, d.sector_normalized);
const pbr_bench = findBench(SECTOR_PBR, d.sector_normalized);

// ─── [RULE-01] PER (FIX #7: 음수 EPS 제외) ─────────────────────
const per_trailing = (d.eps && d.eps > 0) ? ratio(d.current_price, d.eps) : null;
const per_forward  = (d.eps_forward && d.eps_forward > 0) ? ratio(d.current_price, d.eps_forward) : null;

const per_signal = per_trailing
  ? (per_trailing < per_bench.undervalued ? 'UNDERVALUED'
     : per_trailing > per_bench.overvalued ? 'OVERVALUED' : 'FAIR')
  : 'INSUFFICIENT_DATA';

const per_fair_price = (d.eps && d.eps > 0) ? d.eps * per_bench.fair : null;

// ─── [RULE-02] PBR (FIX #8: 음수 장부가 제외) ───────────────────
const pbr = (d.book_value_per_share && d.book_value_per_share > 0)
  ? ratio(d.current_price, d.book_value_per_share)
  : null;

const pbr_signal = pbr
  ? (pbr < pbr_bench.undervalued ? 'UNDERVALUED'
     : pbr > pbr_bench.overvalued ? 'OVERVALUED' : 'FAIR')
  : 'INSUFFICIENT_DATA';

const pbr_fair_price = (d.book_value_per_share && d.book_value_per_share > 0)
  ? d.book_value_per_share * pbr_bench.fair
  : null;

// ─── [RULE-03] DCF ──────────────────────────────────────────────
const FCF              = d.free_cash_flow;
const RAW_GROWTH       = (d.earnings_growth != null && d.earnings_growth > 0) ? d.earnings_growth : 0.10;
const GROWTH_PHASE1    = Math.min(RAW_GROWTH, 0.25);
const GROWTH_PHASE2    = 0.03;   // 터미널 성장률
const DISCOUNT_RATE    = 0.10;   // WACC 기본값
const PROJECTION_YEARS = 10;

// FIX #10: 주식수 - 직접 값 우선, 없으면 시총/주가 (0 나눗셈 방어)
const SHARES = d.shares_outstanding
  ? d.shares_outstanding
  : (d.market_cap && d.current_price && d.current_price > 0)
    ? d.market_cap / d.current_price
    : null;

let dcf_value  = null;
let dcf_signal = 'INSUFFICIENT_DATA';

// FIX #6: 할인율 ≤ 터미널 성장률이면 DCF 불가
if (DISCOUNT_RATE <= GROWTH_PHASE2) {
  dcf_signal = 'INVALID_PARAMETERS';
} else if (FCF && SHARES && FCF > 0) {
  let total_pv   = 0;
  let fcf_year   = FCF;
  let phase1_ok  = true;

  // Phase 1: 1~5년 고성장 (FIX #2: 루프 변수 fcf_year 분리)
  for (let y = 1; y <= 5; y++) {
    fcf_year *= (1 + GROWTH_PHASE1);
    if (fcf_year < 0) { phase1_ok = false; dcf_signal = 'NEGATIVE_GROWTH_PATH'; break; }  // FIX #9
    total_pv += fcf_year / Math.pow(1 + DISCOUNT_RATE, y);
  }

  if (phase1_ok) {
    // Phase 2: 6~10년 선형 둔화 (FIX #2: 별도 변수 fcf_p2)
    let fcf_p2 = fcf_year;
    for (let y = 6; y <= PROJECTION_YEARS; y++) {
      const progress   = (y - 5) / (PROJECTION_YEARS - 5);   // 0.2 → 1.0
      const blend_rate = GROWTH_PHASE1 * (1 - progress) + GROWTH_PHASE2 * progress;
      fcf_p2 *= (1 + blend_rate);
      total_pv += fcf_p2 / Math.pow(1 + DISCOUNT_RATE, y);
    }

    // FIX #3: 터미널 밸류 - fcf_p2는 이미 10년차 값 → 한 번만 성장 적용
    const terminal_value = fcf_p2 * (1 + GROWTH_PHASE2) / (DISCOUNT_RATE - GROWTH_PHASE2);
    total_pv += terminal_value / Math.pow(1 + DISCOUNT_RATE, PROJECTION_YEARS);

    // FIX #17: 베타 연동 안전마진 동적 조정
    const beta = d.beta || 1.0;
    const safety = beta > 2.0 ? 0.55 : beta > 1.5 ? 0.60 : beta > 1.0 ? 0.65 : 0.70;

    dcf_value = (total_pv / SHARES) * safety;

    // FIX #19: current_price=0 방어
    if (d.current_price && d.current_price > 0) {
      dcf_signal = d.current_price < dcf_value * 0.8 ? 'UNDERVALUED'
        : d.current_price > dcf_value * 1.2 ? 'OVERVALUED' : 'FAIR';
    }
  }
}

// ─── [RULE-04] 종합 적정주가 가중평균 ────────────────────────────
const WEIGHTS = { PER: 0.30, PBR: 0.20, DCF: 0.50 };

const valid = [
  per_fair_price ? { val: per_fair_price, w: WEIGHTS.PER, name: 'PER' } : null,
  pbr_fair_price ? { val: pbr_fair_price, w: WEIGHTS.PBR, name: 'PBR' } : null,
  dcf_value      ? { val: dcf_value,      w: WEIGHTS.DCF, name: 'DCF' } : null
].filter(Boolean);

let composite_price = null;
if (valid.length > 0) {
  const wsum   = valid.reduce((a, p) => a + p.val * p.w, 0);
  const wtotal = valid.reduce((a, p) => a + p.w,         0);
  composite_price = wsum / wtotal;   // 정규화된 가중평균
}

// ─── [RULE-05] 투자 등급 ──────────────────────────────────────────
const SKIP = new Set(['INSUFFICIENT_DATA', 'INVALID_PARAMETERS', 'NEGATIVE_GROWTH_PATH']);
const sigs = [per_signal, pbr_signal, dcf_signal].filter(s => !SKIP.has(s));
const n_under = sigs.filter(s => s === 'UNDERVALUED').length;
const n_over  = sigs.filter(s => s === 'OVERVALUED').length;

const GRADE_TABLE = {
  '3_0': { grade: 'STRONG_BUY',  label: '강력매수', color: '#00C851' },
  '2_0': { grade: 'BUY',         label: '매수',     color: '#7CB342' },
  '1_0': { grade: 'WEAK_BUY',   label: '약매수',   color: '#B2DFDB' },
  '1_1': { grade: 'HOLD',        label: '보유',     color: '#FFA726' },
  '0_0': { grade: 'HOLD',        label: '보유',     color: '#FFA726' },
  '0_1': { grade: 'WEAK_SELL',  label: '약매도',   color: '#EF9A9A' },
  '0_2': { grade: 'SELL',        label: '매도',     color: '#F44336' },
  '0_3': { grade: 'STRONG_SELL', label: '강력매도', color: '#B71C1C' }
};

const gkey  = `${n_under}_${n_over}`;
const grade = GRADE_TABLE[gkey] || { grade: 'NEUTRAL', label: '중립', color: '#9E9E9E' };

// FIX #19: current_price=0 upside 무한대 방지
const upside = (composite_price && d.current_price && d.current_price > 0)
  ? ((composite_price - d.current_price) / d.current_price * 100).toFixed(2) + '%'
  : 'N/A';

// FIX #18: 가중 데이터 품질 점수 (0값 ≠ 누락)
const Q_FIELDS = [
  { v: d.eps,                w: 0.25 },
  { v: d.book_value_per_share, w: 0.25 },
  { v: d.free_cash_flow,     w: 0.25 },
  { v: d.revenue,            w: 0.15 },
  { v: d.net_income,         w: 0.10 }
];
const data_quality_score = Math.round(
  Q_FIELDS.filter(f => f.v !== null && f.v !== undefined).reduce((s, f) => s + f.w, 0) * 100
);

return [{
  json: {
    ...d,
    data_quality_score,
    models_available: valid.map(p => p.name),
    valuation: {
      per: {
        trailing:   per_trailing?.toFixed(2),
        forward:    per_forward?.toFixed(2),
        signal:     per_signal,
        fair_price: per_fair_price?.toFixed(2),
        benchmark:  per_bench
      },
      pbr: {
        value:      pbr?.toFixed(2),
        signal:     pbr_signal,
        fair_price: pbr_fair_price?.toFixed(2),
        benchmark:  pbr_bench
      },
      dcf: {
        intrinsic_value:   dcf_value?.toFixed(2),
        signal:            dcf_signal,
        growth_rate_used:  pct(GROWTH_PHASE1),
        terminal_growth:   pct(GROWTH_PHASE2),
        discount_rate:     pct(DISCOUNT_RATE)
      },
      composite: {
        fair_price:        composite_price?.toFixed(2),
        current_price:     d.current_price,
        upside_potential:  upside,
        investment_grade:  grade.grade,
        grade_label:       grade.label,
        grade_color:       grade.color,
        models_used:       valid.length,
        models_list:       valid.map(p => p.name).join('+'),
        data_quality_score
      }
    },
    calculated_at: new Date().toISOString()
  }
}];

