// ================================================================
// LAYER 4 - NODE 4-4: Gemini + Claude 결과 통합 v2.1
// FIX #13: 노드명 명시 참조 (입력 순서 가정 제거)
// FIX #20: JSON 파싱 try-catch + 마크다운 코드블록 제거
// ================================================================

// FIX #20: 안전한 JSON 파싱 (마크다운 코드블록 자동 제거)
const safeParse = (text, src) => {
  if (!text) return { _error: `Empty: ${src}` };
  const clean = text.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/i, '').trim();
  try {
    return JSON.parse(clean);
  } catch (e) {
    return { _error: e.message, _raw: clean.slice(0, 200) };
  }
};

// FIX #13: 노드명 명시 참조 (실행 안된 노드 안전 처리)
const gemini_raw = (() => { try { return $('Gemini 분석').first().json; } catch(e) { return {}; } })();
const claude_raw = (() => { try { return $('Claude 분석').first().json; } catch(e) { return {}; } })();
const base       = $('패킷 구조화').first().json;

const gemini = safeParse(
  gemini_raw.candidates?.[0]?.content?.parts?.[0]?.text || '',
  'Gemini'
);
const claude = safeParse(
  claude_raw.content?.[0]?.text || '',
  'Claude'
);

// 파싱 실패 시 안전 기본값
const g = { time_horizon: '중기', bull_case: 'N/A', bear_case: 'N/A', catalyst_events: [], ...gemini };
const c = { risk_grade: 'MEDIUM', risk_score: 50, red_flags: [], ...claude };

// 리스크 VERY_HIGH 시 등급 표시 하향 (실제 grade 값은 유지)
const combined_signal = c.risk_grade === 'VERY_HIGH'
  ? 'DOWNGRADE_' + base.payload.valuation.composite.investment_grade
  : base.payload.valuation.composite.investment_grade;

return [{
